import{_ as t,o as e,c as a,ag as _}from"./chunks/framework.DaAXJYxM.js";const u=JSON.parse('{"title":"第30章 废话","description":"","frontmatter":{},"headers":[],"relativePath":"第30章_废话.md","filePath":"第30章_废话.md"}'),o={name:"第30章_废话.md"};function r(n,p,s,c,i,d){return e(),a("div",null,[...p[0]||(p[0]=[_('<h1 id="第30章-废话" tabindex="-1">第30章 废话 <a class="header-anchor" href="#第30章-废话" aria-label="Permalink to &quot;第30章 废话&quot;">​</a></h1><p>她回来之后，我们约了一次。</p><p>是她提的。那天晚上她说，明天晚自习之前，你在老地方等我。</p><p>老地方就是三楼西边那个天井边上的栏杆。我在那儿站了小半个学期，她从来不知道我站的是哪一根栏杆。</p><p>我说，好。</p><p>她说，你别早去。</p><p>我说，几点。</p><p>她说，你正常去就行。</p><p>第二天下午最后一节课下课，我照常从东边楼梯下去，在食堂吃了一顿很快的饭，然后回教学楼。</p><p>饭我没吃出味道。食堂那天有白菜炖粉条，是北方做法，我吃了一碗就没再添。</p><p>走到三楼西边那条走廊的时候，天已经暗了。连廊的灯没开，只有教室里的光从玻璃里透出来。我走到栏杆那儿站着。</p><p>等了大概十分钟。</p><p>楼梯口那边有脚步声。很轻，走走停停，像是在犹豫。</p><p>她上来了。</p><p>她走到我旁边，隔了大概一步远。</p><p>她说，原来是这儿。</p><p>我说，嗯。</p><p>她把手搭在栏杆上，往下看。天井里黑着，什么都看不见。</p><p>她说，你来过多少次。</p><p>我说，不记得了。</p><p>她说，你说谎。</p><p>我说，还是记一点的。</p><p>她说，多少次。</p><p>我说，几十次。</p><p>她没说话。她的手在栏杆上敲了两下。</p><p>中间有一阵子来人了。是两个值日的学生，提着水桶从走廊那头过来，桶里的水一晃一晃的。</p><p>我们两个往两边分开了半步。她把手从栏杆上收回去，低头看自己的鞋。我转过去看天井，装成在看什么。</p><p>那两个学生从我们中间走过去，看都没看我们一眼。水桶在地上拖出声音，很近。</p><p>他们拐过弯，声音就远了。</p><p>我们又站回原来的位置。她往我这边挪了半步，比刚才近一点。</p><p>她说，你说我们这样像什么。</p><p>我说，不知道。</p><p>她说，像两个在同一条街上等人的人。</p><p>我说，等谁。</p><p>她说，不知道。</p><p>那天晚上我们在那儿站了大概二十分钟。</p><p>中间她说了很多话。她说她最近在家里被说了两次，一次因为成绩，一次因为她出门没跟她妈说。她说她妹妹上个月考了个好名次，她妈在饭桌上讲了三天。她说她这半年瘦了四斤，她自己称的。</p><p>她说这些的时候语气很平，跟讲别人的事一样。我一句一句接。</p><p>我接的时候在看她的侧脸。她比我开学那次见到的时候瘦了一点。她的头发扎起来了，脖子后面那一小块有一层细汗，不知道是刚跑上来的还是什么。</p><p>有一件事我一直想问。那三天她不说话的事，我想问她到底在想什么。</p><p>我没问。</p><p>我站在那儿，手放在栏杆上，那个问题在嘴里转了几圈，最后没出去。</p><p>后来她说，我该回去了。</p><p>我说，好。</p><p>她说，晚自习要默写，我得去背。</p><p>我说，那你去。</p><p>她走了两步，回过头。</p><p>她说，你不问我吗。</p><p>我说，问什么。</p><p>她说，你知道我问的是什么。</p><p>我站在那儿没动。我能听见楼下有人在喊人，喊的是别人的名字。</p><p>最后我说，你要是想说，你自己会说。</p><p>她看了我一会儿。她没说想，也没说不想。</p><p>她说，我走了。</p><p>她下楼了。</p><p>那天我站在那儿又站了一会儿才下去。晚自习的铃响的时候我刚坐到座位上。</p><p>沈聿在旁边做题，抬头看了我一眼，什么都没说。</p><p>那天晚上她十一点多发来一条消息。</p><p>她说：你说食堂那个鱼是不是有刺。</p><p>我说：有。</p><p>她说：我今天被扎了。</p><p>我说：扎哪了。</p><p>她说：上颚。</p><p>我说：那你还吃。</p><p>她说：我饿。</p><p>就这几句。</p><p>我看着那几句，看了一会儿。然后我回了一句。</p><p>我说：下次挑刺少的。</p><p>她说：你还挺懂。</p><p>我说：我怕你又被扎。</p><p>她说：被扎了也没事。</p><p>她说完这句就下线了。</p><p>那天晚上快两点的时候，我起来上了个厕所。回来的时候别的都睡了，我拿手机看了一眼，她没有再发消息。</p><p>我翻了翻我们那几天的记录。三天半里，我发过十一条，她回过两条。</p><p>那两条我看了两遍。第一条是“嗯”，第二条是“知道了”。</p><p>我能把那两条背下来。</p><p>那天晚上我躺在床上，把那二十分钟回想了一遍。</p><p>我一直在想一个问题：那三天的事，我们还一个字都没提。</p><p>按道理，吵完架要说开的。要说你为什么生气，我哪里做错了，下次怎么办。我在南雾看过别人吵完架是这样和好的。</p><p>我跟她没有。</p><p>她第二天给我发了一条&quot;鱼有没有刺&quot;，这件事就过去了。</p><p>我那时候不太接受这件事。我觉得这不叫和好，这叫躲。</p><p>后来我懂了。这大概就是我们两个唯一会用的和好方式。我们不会坐下来把话说清楚，我们只会把那件事绕过去，然后从旁边重新开始。</p><p>绕过去的东西不会消失。它会沉到底下去。</p><p>我们两个在那两年里沉了很厚的一层东西。</p><p>那层东西有多厚，我直到最后一天才知道。</p><p>那几天里我数了一下。我们那次不说话，一共是三天半。三天半之后的一句&quot;鱼有没有刺&quot;，就是全部的交代。</p><p>我后来想过很多次：如果那天晚上我把那个问题问出来了，会怎么样。</p><p>我想过很多种可能，每一种都比现在好。</p><p>可那时候的我就是问不出来。倒不是因为不敢，是因为我觉得既然她肯回来了，那就是不用问了。</p><p>这个想法错了。</p><p>接下来的两个星期，我们过得很好。她天天上线，一天不落，话也比以前多。</p><p>我在那本本子上记了那几天的日子。写下“十二月二十三号，她在老地方站了二十分钟”的时候，我犹豫了一下。</p><p>我想在最前面加上“第一次”。</p><p>加完看了看，又划掉了。</p><p>那时候我不知道自己为什么要划。后来我想明白了：我不想让那变成一件可以倒数的事。</p><p>那两星期里还有一件事。</p><p>有一天中午我在食堂门口等她，等到一半她发消息说她不来了。我问为什么，她说她们班主任在查人，她走不开。</p><p>我说好。</p><p>她说，你别站那儿。</p><p>我说，已经走了。</p><p>她说，那就好。</p><p>那天中午我一个人吃了一顿饭。吃完回教室的路上，我在二楼转过一下，往她们班那个方向看了一眼。门是关着的。</p><p>我看完就走了。</p><p>那时候我以为这种小事不算什么。一顿饭不吃，一次见面取消，又不会怎么样。</p><p>后来我才知道，就是这些小事。一顿一顿攒起来的，一件一件取消掉的。</p>',106)])])}const m=t(o,[["render",r]]);export{u as __pageData,m as default};
